      "parameters": {
        "type": "object",
        "properties": {
          "po_id": {
            "type": "string",
            "description": "Purchase order id."
          },
          "amount_cents": {
            "type": "integer",
            "description": "Amount in cents."
          },
          "idempotency_key": {
            "type": "string",
            "nullable": true,
            "description": "Optional key; a retry with the same key never pays twice."
          }
        },
        "required": [
          "po_id",
          "amount_cents"
        ]
      },
      "return": {
        "type": "object",
        "additionalProperties": {}
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "record_goods_receipt",
